async def _run_container_engine_cmd(self, container, kind):
        """Stream logs without blocking the event loop; enforce the run deadline."""
        container_id = container['Id']
        stdout_chunks, stderr_chunks = ([], [])
        websocket, stream = (None, None)
        return_code = {'StatusCode': 1}
        start = time.time()
        completed = threading.Event()
        lifecycle_lock = threading.Lock()
        timeout_flag = self._execution_time_limit_exceeded
        deadline = self._execution_deadline
        if deadline is None:
            deadline = time.monotonic() + self.execution_time_limit

        def expire_container():
            with lifecycle_lock:
                if completed.is_set():
                    return
                timeout_flag.set()
            try:
                client.remove_container(container_id, v=True, force=True)
            except docker.errors.NotFound:
                pass
            except Exception as error:
                logger.error(f'Deadline cleanup for {container_id} failed: {error}')
        watchdog = threading.Timer(max(0, deadline - time.monotonic()), expire_container)
        watchdog.daemon = True
        watchdog.start()
        exhausted = object()

        def next_log():
            return next(stream, exhausted)
        try:
            if not Settings.COMPUTE_WORKER_DISABLE_LOG_UPLOAD:
                try:
                    websocket_url = f'{self.websocket_url}?kind={kind}'
                    websocket = await asyncio.wait_for(websockets.connect(websocket_url), timeout=10.0)
                except Exception as error:
                    logger.error(f'Cannot connect log websocket: {error}')
            if timeout_flag.is_set():
                raise ExecutionTimeLimitExceeded()
            await asyncio.to_thread(client.start, container=container_id)
            stream = await asyncio.to_thread(client.attach, container_id, demux=True, stream=True, logs=True)
            while True:
                log = await asyncio.to_thread(next_log)
                if log is exhausted:
                    break
                for index, chunks in ((0, stdout_chunks), (1, stderr_chunks)):
                    if log[index] is None:
                        continue
                    chunks.append(log[index])
                    message = log[index].decode(errors='replace')
                    if index == 0:
                        logger.info(message)
                    else:
                        logger.error(message)
                    if websocket is not None:
                        try:
                            await websocket.send(json.dumps({'kind': kind, 'message': message}))
                        except Exception as error:
                            logger.error(error)
            return_code = await asyncio.to_thread(client.wait, container_id)
        except ExecutionTimeLimitExceeded:
            timeout_flag.set()
        except (docker.errors.APIError, Exception) as error:
            logger.error(f'Container {container_id} execution failed: {error}')
        finally:
            with lifecycle_lock:
                completed.set()
            watchdog.cancel()
            try:
                await asyncio.to_thread(client.remove_container, container_id, v=True, force=True)
            except docker.errors.NotFound:
                pass
            except Exception as error:
                logger.error(f'Container {container_id} cleanup failed: {error}')
            if stream is not None:
                try:
                    await asyncio.to_thread(stream.close)
                except Exception as error:
                    logger.debug(f'Cannot close log stream for {container_id}: {error}')
            await asyncio.to_thread(watchdog.join)
            if websocket is not None:
                try:
                    await asyncio.wait_for(websocket.close(), timeout=5.0)
                    await asyncio.wait_for(websocket.wait_closed(), timeout=5.0)
                except Exception as error:
                    logger.error(error)
